    [STAThread] static int Main(string[] args){try{if(args.Length==2&&args[0]=="--self-test"){Verify(args[1]);return 0;}Application.SetHighDpiMode(HighDpiMode.PerMonitorV2);Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);if(args.Length==2&&args[0]=="--preview"){Application.Run(new SetupForm(args[1]));return 0;}if(args.Length==2&&args[0]=="--uninstall-worker"){try{using var owner=Process.GetProcessById(int.Parse(args[1]));if(!owner.WaitForExit(30000))throw new InvalidOperationException("Close the original uninstall window and retry.");}catch(ArgumentException){}Application.Run(new SetupForm(uninstall:true,worker:true));return 0;}Application.Run(new SetupForm(uninstall:args.Contains("--uninstall")));return 0;}catch(Exception ex){if(args.Length==2)File.WriteAllText(args[1]+".error.txt",ex.ToString());else MessageBox.Show(ex.Message,"Minecraft Harbor Setup");return 1;}}
    static byte[] Payload(){using var stream=Assembly.GetExecutingAssembly().GetManifestResourceStream("Harbor.Payload.zip")!;using var memory=new MemoryStream();stream.CopyTo(memory);byte[] bytes=memory.ToArray();using var hashStream=Assembly.GetExecutingAssembly().GetManifestResourceStream("Harbor.Payload.sha256")!;using var reader=new StreamReader(hashStream);if(Convert.ToHexString(SHA256.HashData(bytes))!=reader.ReadToEnd().Trim())throw new InvalidDataException("Installer payload failed verification.");return bytes;}
