    internal static string[] Extract(string root,Action<int>? progress=null){using var zip=new ZipArchive(new MemoryStream(Payload()),ZipArchiveMode.Read);var entries=zip.Entries.Where(e=>!e.FullName.EndsWith('/')).ToArray();if(entries.Length==0||entries.Select(e=>e.FullName).Distinct(StringComparer.OrdinalIgnoreCase).Count()!=entries.Length)throw new InvalidDataException("Invalid installer contents.");foreach(var entry in entries)SafeTarget(root,entry.FullName);Directory.CreateDirectory(root);int done=0;foreach(var entry in entries){string target=SafeTarget(root,entry.FullName);Directory.CreateDirectory(Path.GetDirectoryName(target)!);using var input=entry.Open();using var output=File.Create(target);input.CopyTo(output);if(output.Length!=entry.Length)throw new IOException("Incomplete installer file.");progress?.Invoke(++done*100/entries.Length);}return entries.Select(e=>e.FullName).ToArray();}
    static void RequireClosed(string root)=>HarborUpdates.UpdateShutdown.CloseApplication(Path.Combine(root,"Minecraft Harbor.exe"),TimeSpan.FromMinutes(10));
    internal static void Install(bool desktop,Action<int> progress,bool integrate=true){RequireClosed(InstallRoot);string staged=InstallRoot+"-setup-"+Guid.NewGuid().ToString("N");string[] files=Extract(staged,progress);Directory.CreateDirectory(InstallRoot);string recovery=InstallRoot+"-previous-"+Guid.NewGuid().ToString("N");Directory.CreateDirectory(recovery);var copied=new List<string>();try{foreach(string file in files){string destination=SafeTarget(InstallRoot,file);Directory.CreateDirectory(Path.GetDirectoryName(destination)!);if(File.Exists(destination)){string saved=SafeTarget(recovery,file);Directory.CreateDirectory(Path.GetDirectoryName(saved)!);File.Copy(destination,saved);}copied.Add(file);File.Copy(SafeTarget(staged,file),destination,true);}File.Copy(Environment.ProcessPath!,Path.Combine(InstallRoot,"Uninstall Minecraft Harbor.exe"),true);File.WriteAllText(Path.Combine(InstallRoot,"installed-files.json"),JsonSerializer.Serialize(files));if(integrate){Shortcut(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.StartMenu),"Programs","Minecraft Harbor.lnk"));if(desktop)Shortcut(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),"Minecraft Harbor.lnk"));using var key=Registry.CurrentUser.CreateSubKey("Software\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\MinecraftHarbor");key.SetValue("DisplayName","Minecraft Harbor");key.SetValue("DisplayVersion","1.4.0");key.SetValue("Publisher","Rise Digital");key.SetValue("InstallLocation",InstallRoot);key.SetValue("DisplayIcon",Path.Combine(InstallRoot,"Minecraft Harbor.exe"));key.SetValue("UninstallString","\""+Path.Combine(InstallRoot,"Uninstall Minecraft Harbor.exe")+"\" --uninstall");key.SetValue("NoModify",1);key.SetValue("NoRepair",1);}}catch{foreach(string file in copied){string target=SafeTarget(InstallRoot,file),saved=SafeTarget(recovery,file);if(File.Exists(saved))File.Copy(saved,target,true);else if(File.Exists(target))File.Delete(target);}throw;}finally{Clea