    static void Shortcut(string path){Type type=Type.GetTypeFromProgID("WScript.Shell")??throw new IOException("Windows shortcut service unavailable");dynamic shell=Activator.CreateInstance(type)!;try{dynamic link=shell.CreateShortcut(path);try{link.TargetPath=Path.Combine(InstallRoot,"Minecraft Harbor.exe");link.WorkingDirectory=InstallRoot;link.Description="Minecraft Harbor — manage your Minecraft servers";link.IconLocation=link.TargetPath+",0";link.Save();}finally{System.Runtime.InteropServices.Marshal.FinalReleaseComObject(link);}}finally{System.Runtime.InteropServices.Marshal.FinalReleaseComObject(shell);}}
    static void CleanKnownFolder(string root){if(!Directory.Exists(root))return;foreach(string path in Directory.EnumerateFiles(root,"*",SearchOption.AllDirectories)){SafeTarget(root,Path.GetRelativePath(root,path).Replace('\\','/'));File.Delete(path);}foreach(string path in Directory.EnumerateDirectories(root,"*",SearchOption.AllDirectories).OrderByDescending(p=>p.Length))Directory.Delete(path);Directory.Delete(root);}
    internal static void Uninstall(bool integrate=true){RequireClosed(InstallRoot);string manifest=Path.Combine(InstallRoot,"installed-files.json");if(!File.Exists(manifest))throw new InvalidOperationException("The installation record is missing. Your server data has not been touched.");var files=JsonSerializer.Deserialize<string[]>(File.ReadAllText(manifest))??[];foreach(string file in files){string path=SafeTarget(InstallRoot,file);if(File.Exists(path))File.Delete(path);}if(integrate){foreach(string shortcut in new[]{Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.StartMenu),"Programs","Minecraft Harbor.lnk"),Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),"Minecraft Harbor.lnk")})if(File.Exists(shortcut))File.Delete(shortcut);Registry.CurrentUser.DeleteSubKey("Software\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\MinecraftHarbor",false);}File.Delete(manifest);string uninstaller=SafeTarget(InstallRoot,"Uninstall Minecraft Harbor.exe");if(File.Exists(uninstaller))File.Delete(uninstaller);foreach(string directory in Directory.EnumerateDirectories(InstallRoot,"*",SearchOption.AllDirectories).OrderByDescending(p=>p.Length)){SafeTarget(InstallRoot,Path.GetRelativePath(InstallRoot,directory).Replace('\\','/'));if(!Directory.EnumerateFileSystemEntries(directory).Any())Directory.Delete(directory);}if(!Directory.EnumerateFileSystemEntries(InstallRoot).Any())Directory.Delete(InstallRoot);}
    internal static void StartUninstallWorker(){string temporary=Path.Combine(Path.GetTempPath(),"Minecraft-Harbor-Uninstall-"+Guid.NewGuid().ToString("N")+".exe");File.Copy(Environment.ProcessPath!,temporary);var start=new ProcessStartInfo(temporary){UseShellExecute=true};start.ArgumentList.Add("--uninstall-worker");start.ArgumentList.Add(Environment.ProcessId.ToString());Process.Start(start);}
    static void Verify(string report){string root=Path.Combine(Path.GetDirectoryName(Path.GetFullPath(report))!,"installer-test-"+Guid.NewGuid().ToString("N"));string[] files=Extract(root);if(!files.Contains("Minecraft Harbor.exe")||!files.Contains("client-setup/Minecraft-Harbor-Agent-Setup.exe")||files.Any(f=>f.StartsWith("server/")||f=="settings.json"||f=="library.json"||f.StartsWith("backups/")||f.Contains("minecraftinstance.json")))throw new Exception("Payload is incomplete or includes private server data.");string client=SafeTarget(root,"client-setup/Minecraft-Harbor-Agent-Setup.exe");if(Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(client)))!=File.ReadAllText(client+".sha256").Trim())throw new Exception("Client installer checksum mismatch.");bool rejected=false;try{SafeTarget(root,"../outside");}catch(InvalidDataException){rejected=true;}if(!rejected)throw new Exception("Unsafe payload path accepted.");foreach(string file in files)if(!File.Exists(SafeTarget(root,file)))throw new Exception("Missing extracted file.");try{TestRoot=Path.Combine(root,"installed");Install(false,_=>{},false);string privateFile=Path.Combine(TestRoot,"my-world","level.dat");Directory.CreateDirectory(Path.GetDirectoryName(privateFile)!);File.WriteAllText(privateFile,"keep my save");Install(false,_=>{},false);if(File.ReadAllText(privateFile)!="keep my save")throw new Exception("Update removed user data.");Uninstall(false);if(File.Exists(Path.Combine(TestRoot,"Minecraft Harbor.exe"))||File.ReadAllText(privateFile)!="keep my save")throw new Exception("Uninstaller removed user data or left the app.");}finally{TestRoot=null;}File.WriteAllText(report,JsonSerializer.Serialize(new{passed=true,fileCount=files.Length,payloadVerified=true,installUpdateUninstallPassed=true,userDataPreserved=true,privateServerIncluded=false,shortcutsOrRegistryChanged=false},new JsonSerializerOptions{WriteIndented=true}));}
}
